export function renderGrowth(c){
 const {esc:e,icon,btn,heading,state,role,me,selectedStudent:sid,data:g,period,tab}=c;
 const s=state.students.find(x=>x.id===sid);
 if(!s)return heading('成长画像','把研究进展、材料依据与下一步行动连接起来。')+'<section class="card"><div class="empty">当前没有可访问的学生档案。</div></section>';
 const actions=`<select id="portrait-student" aria-label="选择画像学生">${state.students.map(x=>`<option value="${x.id}" ${x.id===sid?'selected':''}>${e(x.name)}</option>`).join('')}</select><select id="growth-period" aria-label="画像学年"><option value="">全部记录</option>${(g?.periods||[]).map(p=>`<option value="${e(p)}" ${period===p?'selected':''}>${e(p)}</option>`).join('')}</select>${btn('导出画像','export:portrait',false,'download')}`;
 let html=`<section class="campus-career-hero"><h1>${role==='student'?'我的学业生涯':'学生学业生涯'}</h1><p>研究生成长画像 · 每一步积累都有据可循</p></section>`+heading('研究成长画像','每一项进展都有来源，每一次反馈都连接下一步行动。',actions).replace('<h1>','<h2>').replace('</h1>','</h2>');
 if(role!=='student')html+=`<div class="growth-tabs"><button class="${tab==='personal'?'active':''}" data-action="growth-tab:personal">${icon('users',15)} 个人成长档案</button><button class="${tab==='cohort'?'active':''}" data-action="growth-tab:cohort">${icon('chart',15)} 培养范围总览</button><span>材料观察 · 不生成学生排名</span></div>`;
 if(tab==='cohort'&&role!=='student')return html+renderCohort(c);
 if(!g)return html+'<section class="card"><div class="empty">正在读取成长记录…</div></section>';
 const warnings=g.warnings.filter(w=>['open','tracking'].includes(w.status)),goals=g.entries.filter(x=>['goal','milestone'].includes(x.kind)),latestGoal=goals.find(x=>x.kind==='goal'&&x.status==='planned')||goals.find(x=>x.kind==='goal'),feedback=g.entries.filter(x=>['feedback','reflection'].includes(x.kind));
 const tags=s.direction&&s.direction!=='待补录'?[s.direction]:[];
 html+=`<div class="career-timeline"><section class="career-section"><div class="career-label"><h2>基本信息</h2><span>${icon('users',17)}</span></div><div class="career-body"><section class="growth-banner"><div class="growth-id"><div class="growth-avatar">${e(s.name.replace(/（模拟）$/,'').slice(-2))}</div><div><div class="growth-overline">学生培养档案</div><h2>${e(s.name.replace(/（模拟）$/,''))} <span>${e(s.year)}${s.degree&&s.degree!=='未标注'?' · '+e(s.degree):''}</span></h2><p>${e(s.number)} · ${e(s.major)}</p><div class="growth-tags">${s.name.endsWith('（模拟）')?'<span class="badge amber">模拟数据</span>':''}${tags.map(t=>`<span>${e(t)}</span>`).join('')||'<span>研究方向待补录</span>'}</div></div></div><div class="growth-goal"><small>当前研究目标</small><h3>${e(latestGoal?.title||'让下一步研究计划更清晰')}</h3><p>${e(latestGoal?.body||'记录阶段目标、关键节点与支持需求，逐步积累研究过程。')}</p><button data-action="growth-new:goal" class="linkbtn">${icon('plus',13)} ${latestGoal?'新增阶段目标':'记录研究目标'}</button></div><div class="growth-banner-status"><span class="badge ${warnings.length?'amber':''}">${warnings.length?`${warnings.length} 项需要跟进`:'暂无待处理预警'}</span><small>${period?e(period):'全部学年 · 当前有效档案'}</small><small>指导：${e(s.teacher)}</small></div></section>`;
 html+=`<div class="growth-stats">${[['paper','可见材料记录',g.counts.materials,'已登记与正式归档分别统计'],['archive','有效归档',g.counts.archives,`${g.counts.papers} 份论文申报 · ${g.counts.annual} 份年度报告`],['chart','材料覆盖',`${g.coverage} / 6`,'有来源依据的观察方向'],['bell','待跟进事项',warnings.length,'当前跨学年的材料与计划提醒']].map(([i,t,n,d])=>`<div class="growth-stat"><span class="growth-stat-icon">${icon(i,18)}</span><p>${t}</p><strong>${n}</strong><small>${d}</small></div>`).join('')}</div>`;
 html+='</div></section>';
 html+=`<section class="career-section"><div class="career-label"><h2>成长画像</h2><span>${icon('chart',17)}</span></div><div class="career-body"><div class="growth-main-grid"><section class="card"><div class="card-head"><div><h2>研究成长画像 <span class="badge gray">材料观察</span></h2><p>六类方向的可追溯来源数量，不是能力得分</p></div><button class="linkbtn" data-action="growth-method">指标口径 ↗</button></div><div class="growth-radar-layout">${growthRadar(g.dimensions,e)}<div class="dimension-list">${g.dimensions.map((d,i)=>`<button class="dimension-row" data-action="growth-dimension:${d.key}"><span class="dimension-dot" style="background:${['#447eff','#9071e8','#39b8d8','#b16aa2','#32b6a7','#ff8b60'][i]}"></span><span class="dimension-name">${e(d.label)}<small>${d.count?'来源可追溯':'尚未关联依据'}</small></span><strong>${d.count||'—'}<small>${d.count?'条':''}</small></strong><span class="muted">›</span></button>`).join('')}</div></div><div class="growth-card-foot">${icon('shield',13)} 缺少材料不等于能力不足。点击方向可查看原文、提交版本与依据。</div></section><section class="card next-actions"><div class="card-head"><div><h2>下一步行动</h2><p>把反馈转化为可完成的任务</p></div><span class="badge ${warnings.length?'amber':'gray'}">${warnings.length} 项待跟进</span></div>${warnings.slice(0,3).map(w=>`<div class="growth-action"><span class="growth-action-icon">${icon('bell',16)}</span><div><h3>${e(w.title)}</h3><p>${e(w.text)}</p><button class="linkbtn" data-action="warning:${w.id}">查看依据与跟进 →</button></div></div>`).join('')||`<div class="growth-calm">${icon('check',27)}<h3>当前没有待处理的预警</h3><p>继续积累研究记录，下一步行动由你规划。</p></div>`}<div class="growth-add-action">${btn(role==='student'?'写一条研究反思':'记录阶段反馈','growth-new:'+(role==='student'?'reflection':'feedback'),false,'plus')}</div></section></div>`;
 html+='</div></section>';
 html+=`<section class="career-section"><div class="career-label"><h2>培养进展</h2><span>${icon('task',17)}</span></div><div class="career-body"><div class="growth-main-grid lower"><section class="card"><div class="card-head"><div><h2>研究里程碑</h2><p>计划与完成分别记录，不从材料数量推断进步</p></div>${btn('添加里程碑','growth-new:milestone',false,'plus')}</div><div class="growth-milestones">${goals.length?goals.slice(0,8).map(x=>`<div class="growth-milestone ${x.status==='done'?'done':''}"><span class="milestone-mark">${icon(x.status==='done'?'check':'clock',13)}</span><div><small>${x.kind==='goal'?'阶段目标':'研究节点'} · ${e(x.period)}${x.due_date?' · '+e(x.due_date):''}</small><h3>${e(x.title)}</h3><p>${e(x.body)}</p>${x.source?`<button class="linkbtn" data-action="record:${x.source.submission_id}">查看${x.source.current?'有效':'历史'}来源 V${x.source.number} ↗</button>`:''}</div><div class="milestone-end"><span class="badge ${x.status==='done'?'':'gray'}">${x.status==='done'?'已记录完成':'计划中'}</span>${me.id===x.created_by||me.id===x.student_id?`<button class="linkbtn" data-action="growth-complete:${x.id}:${x.status==='done'?'planned':'done'}">${x.status==='done'?'重新计划':'记录完成'}</button><button class="linkbtn" data-action="growth-edit:${x.id}">调整计划</button>`:''}</div></div>`).join(''):'<div class="empty">尚无研究目标或里程碑。<p>添加第一个计划，把研究目标拆成可执行的步骤。</p></div>'}</div>${feedback.length?`<div class="growth-feedback"><span>${icon('book',15)} ${feedback[0].kind==='feedback'?'阶段反馈':'研究反思'}</span><h3>${e(feedback[0].title)}</h3><p>${e(feedback[0].body)}</p><small>${e(feedback[0].author)} · ${e(feedback[0].created_at.slice(0,10))} · 学生与授权教师可见</small><button class="linkbtn" data-action="growth-history">全部成长记录 →</button></div>`:''}</section><section class="card"><div class="card-head"><div><h2>材料与记录</h2><p>按有效档案的真实归档月份展示</p></div></div>${growthBars(g.trend,e)}<div class="growth-record-summary"><div><strong>${g.counts.pending}</strong><small>正在审核</small></div><div><strong>${g.counts.returned}</strong><small>需要补正</small></div><div><strong>${goals.filter(x=>x.status==='done').length}</strong><small>已完成计划</small></div></div><div class="growth-card-foot">更正只保留一份当前有效认定，曲线不代表能力变化。</div></section></div>`;
 html+='</div></section>';
 html+=`<section class="career-section"><div class="career-label"><h2>成果材料</h2><span>${icon('archive',17)}</span></div><div class="career-body"><section class="card growth-evidence-section"><div class="card-head"><div><h2>成果与证据</h2><p>每项材料都关联明确版本，观察记录可补充研究情境</p></div><div class="actions">${role!=='student'?btn('关联材料观察','growth-new:observation',false,'plus'):''}${btn('全部成长记录','growth-history',false,'history')}</div></div><div class="growth-evidence-grid">${g.sources.map(r=>`<article class="growth-source"><span class="source-kind">${icon(r.kind==='paper'?'paper':'task',17)} ${r.kind==='paper'?'论文申报':'年度报告'}<span>V${r.number}</span></span><h3>${e(r.title)}</h3><p>${e(String(r.form.contribution||r.form.summary||'').slice(0,125))}${String(r.form.contribution||r.form.summary||'').length>125?'…':''}</p><div><small>${e(r.archived_at.slice(0,10))} · ${r.files.length} 份原件</small><button class="linkbtn" data-action="record:${r.submission_id}">查看依据 ↗</button></div></article>`).join('')||'<div class="empty">所选范围暂无已归档材料。<p>材料通过并归档后，会自动进入来源清单。</p></div>'}</div></section><div class="growth-disclosure">${icon('shield',14)} ${e(g.notice)}${period&&g.unassigned_period_count?` 另有 ${g.unassigned_period_count} 份未标注学年的档案，可在“全部记录”中查看。`:''}</div>`;
 return html+'</div></section></div>';
}

function growthRadar(dimensions,e){const max=Math.max(1,...dimensions.map(d=>d.count)),cx=145,cy=136,r=83,point=(i,v)=>{const a=i*Math.PI/3-Math.PI/2;return [cx+Math.cos(a)*r*v,cy+Math.sin(a)*r*v]},count=dimensions.filter(d=>d.count).length;
 return `<div class="growth-radar"><svg viewBox="0 0 290 280" role="img" aria-label="材料来源数量：${dimensions.map(d=>e(d.label)+' '+d.count+' 条').join('，')}。不是能力评分。"><defs><linearGradient id="coverage-fill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#aa223c" stop-opacity=".23"/><stop offset="1" stop-color="#f1bec8" stop-opacity=".06"/></linearGradient></defs>${[.25,.5,.75,1].map(k=>`<polygon points="${dimensions.map((_,i)=>point(i,k).join(',')).join(' ')}" fill="none" stroke="#e2e6f0"/>`).join('')}${dimensions.map((d,i)=>{const p=point(i,1),l=point(i,1.35);return `<line x1="${cx}" y1="${cy}" x2="${p[0]}" y2="${p[1]}" stroke="#e7eaf0"/><text x="${l[0]}" y="${l[1]+4}" text-anchor="middle" font-size="10" fill="#7c8798">${e(d.label)}</text>`}).join('')}${count?`<polygon points="${dimensions.map((d,i)=>point(i,d.count/max).join(',')).join(' ')}" fill="url(#coverage-fill)" stroke="#ae2540" stroke-width="2"/>${dimensions.map((d,i)=>{const p=point(i,d.count/max);return d.count?`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#fff" stroke="#ae2540" stroke-width="2"/>`:''}).join('')}`:`<text x="145" y="139" text-anchor="middle" font-size="12" fill="#8c98aa">待积累材料</text>`}<text x="145" y="272" text-anchor="middle" font-size="10" fill="#8c96a8">刻度 0–${max} 条来源 · ${count}/6 个方向有依据</text></svg></div>`;
}
function growthBars(trend,e){if(!trend.length)return '<div class="growth-chart-empty">尚无归档时间记录<br><small>不会用虚构历史补齐趋势</small></div>';const rows=trend.slice(-8),max=Math.max(1,...rows.map(r=>r.paper+r.annual));return `<div class="growth-bars" role="img" aria-label="${rows.map(r=>e(r.month)+'归档'+(r.paper+r.annual)+'份').join('，')}">${rows.map(r=>`<div class="growth-bar"><span>${r.paper+r.annual}</span><div class="bar-column"><i style="height:${(r.paper+r.annual)/max*90}%"></i></div><small>${e(r.month)}</small></div>`).join('')}</div>`;}

export function renderCohort(c){const {overview:o,esc:e,btn,query}=c;if(!o)return '<section class="card"><div class="empty">正在读取培养范围总览…</div></section>';const rows=o.items.filter(s=>s.name.includes(query));return `<section class="card"><div class="card-head"><div><h2>培养范围内的材料概览</h2><p>${o.items.length} 位学生 · ${o.items.filter(s=>s.coverage).length} 位有可追溯材料 · 不展示正式排名</p></div></div><div class="toolbar"><input id="list-query" value="${e(query)}" placeholder="搜索学生姓名" aria-label="搜索画像学生">${btn('查询','search-list',false,'search')}</div><div class="table-wrap"><table class="cohort-table"><thead><tr><th>学生</th>${o.dimensions.map(d=>`<th>${e(d.label)}</th>`).join('')}<th>待跟进</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${e(s.name)}</strong><small style="display:block;margin-top:6px">${s.counts.archives} 份有效档案</small></td>${s.dimensions.map(d=>`<td><span class="coverage-cell ${d.count?'has-evidence':''}">${d.count?d.count+' 条':'—'}</span></td>`).join('')}<td><span class="badge ${s.warnings?'amber':'gray'}">${s.warnings} 项</span></td><td><button class="linkbtn" data-action="growth-person:${s.student_id}">个人画像 ↗</button></td></tr>`).join('')}</tbody></table></div><div class="growth-card-foot">${e(o.notice)} “—”表示尚无关联材料，不表示零分。</div></section>`;}

export function renderWarnings(c){const {warnings:all,esc:e,icon,btn,heading,role,filter,query,student,manualAlerts}=c;let rows=all.filter(w=>(filter==='all'||filter==='active'&&['open','tracking'].includes(w.status)||filter==='closed'&&['resolved','dismissed','cleared'].includes(w.status)||filter==='high'&&w.severity==='high'&&['open','tracking'].includes(w.status))&&(!query||(student(w.student).name+w.title+w.text).includes(query)));const active=all.filter(w=>['open','tracking'].includes(w.status));
 return heading(role==='student'?'我的提醒与行动':'预警与培养支持','先看事实依据，再记录支持行动；预警不等于学生能力结论。',btn('预警规则','warning-method',false,'shield')+btn('刷新预警','refresh',true,'history'))+`<div class="warning-metrics">${[['待跟进事项',active.length,'bell'],['优先核验',active.filter(w=>w.severity==='high').length,'shield'],['涉及学生',new Set(active.map(w=>w.student)).size,'users'],['已处理 / 已消除',all.length-active.length,'check']].map(([t,n,i])=>`<div><span>${icon(i,17)} ${t}</span><strong>${n}</strong></div>`).join('')}</div><section class="card"><div class="tabs">${[['active','待跟进'],['high','优先核验'],['closed','已处理'],['all','全部记录']].map(([v,t])=>`<button class="tab ${filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><div class="toolbar"><input id="list-query" aria-label="搜索预警" value="${e(query)}" placeholder="搜索学生、预警事项或依据">${btn('查询','search-list',false,'search')}</div><div class="warning-list">${rows.map(w=>`<article class="warning-item ${w.severity==='high'?'priority':''}"><span class="warning-item-icon">${icon(w.status==='cleared'?'check':'bell',19)}</span><div class="warning-item-body"><div class="warning-item-title"><h3>${e(w.title)}</h3><span class="badge ${['open','tracking'].includes(w.status)?'amber':'gray'}">${{open:'待跟进',tracking:'跟进中',resolved:'已处理',dismissed:'已排除',cleared:'条件已消除'}[w.status]}</span></div><p>${w.active?'':'触发时依据：'}${e(w.text)}</p><div class="warning-meta"><span>${e(student(w.student).name)}</span><span>${{overdue:'任务截止规则',due_soon:'7 天内截止',returned:'材料补正规则',agent_exception:'审核异常规则',goal_overdue:'计划到期规则'}[w.kind]}</span><span>${w.history.length} 条跟进记录</span></div>${w.note?`<div class="warning-last-note">最近跟进：${e(w.note)}</div>`:''}</div><button class="btn" data-action="warning:${w.id}">${role==='student'?'查看依据':'查看与跟进'} →</button></article>`).join('')||`<div class="growth-calm">${icon('check',30)}<h3>当前筛选下没有预警</h3><p>系统依据任务、材料与计划的真实状态生成提醒。</p></div>`}</div></section><section class="card" style="margin-top:22px"><div class="card-head"><div><h2>站内沟通与提醒</h2><p>保留原有人工提醒，可填写反馈与处理状态</p></div><span class="badge gray">${manualAlerts.length} 项</span></div>${manualAlerts.map(a=>`<div class="notice"><div style="flex:1"><h3>${e(student(a.student).name)} · ${e(a.title)}</h3><p>${e(a.text)}</p>${a.note?`<p>${e(a.note)}</p>`:''}</div>${btn(a.status==='done'?'查看记录':'记录反馈','alert:'+a.id)}</div>`).join('')||'<div class="growth-card-foot">暂无人工创建的站内提醒。</div>'}</section><div class="growth-disclosure">${icon('shield',14)} 同一事项按来源版本去重；材料提交、审核完成或计划完成后，对应条件自动消除。跟进内容向学生与授权教师开放。</div>`;
}
